const XLSX = require\('xlsx'\);
const wb = XLSX.readFile\('./plantillas.xlsx'\);

function pad\(n\) { return String\(n\).padStart\(12, '0'\); }
function productUUID\(id\) { return '00000000-0009-0000-0000-' + pad\(id\); }
function plantillaUUID\(id\) { return '00000000-000a-0000-0000-' + pad\(id\); }
function itemUUID\(idx\) { return '00000000-000b-0000-0000-' + pad\(idx\); }

const catalogo = XLSX.utils.sheet_to_json\(wb.Sheets['catalogo']\);
const plantillaRows = XLSX.utils.sheet_to_json\(wb.Sheets['Plantillas']\);
const elementos = XLSX.utils.sheet_to_json\(wb.Sheets['elementos']\);

const products = catalogo.map\(p => \({
  id: productUUID\(p.ID\),
  name: p.name || '',
  description: p.description || null,
  currency: p.currency || 'MXN',
  cost_base: p.cost_base || 0,
  utility_fixed: p.utility_fixed || 0,
  utility_factor: p.utility_factor || 1,
}\)\);

const plantillas = plantillaRows.map\(pl => \({
  id: plantillaUUID\(pl['Plantilla ID']\),
  nombre: pl['Plantilla'],
  requerimiento: pl['Requerimiento'] || null,
}\)\);

const items = elementos.map\(\(el, i\) => \({
  id: itemUUID\(i + 1\),
  plantilla_id: plantillaUUID\(el['plantilla id']\),
  product_id: productUUID\(el['producto id']\),
  qty: el['piezas'] || 1,
  discount_percent: el['descuento'] || 0,
  sequence: \(i + 1\) * 10,
}\)\);

const output = JSON.stringify\({ products, plantillas, items }, null, 2\);
require\('fs'\).writeFileSync\('./lib/plantillas-seed-data.json', output\);
console.log\('products:', products.length, 'plantillas:', plantillas.length, 'items:', items.length\);
")
